#include "diagnostics/PlatformDiagnosticRules.hpp"
#include "platform/AircraftPlatformCatalog.hpp"
#include <algorithm>
#include <iomanip>
#include <sstream>
namespace nexvary::avionics { namespace {DiagnosticSeverity sev(const std::string& s){if(s=="FAULT")return DiagnosticSeverity::Fault;if(s=="WARNING")return DiagnosticSeverity::Warning;return DiagnosticSeverity::Advisory;}bool hit(const PlatformDiagnosticRule& r,double v){return r.comparison=="below"?v<r.threshold:r.comparison=="above"?v>r.threshold:false;}std::string num(double v){std::ostringstream o;o<<std::fixed<<std::setprecision(1)<<v;return o.str();}void finish(std::string_view p,DiagnosticSummary& s){s.advisoryCount=s.warningCount=s.faultCount=0;double penalty=0;for(const auto& f:s.findings){if(f.severity==DiagnosticSeverity::Fault){++s.faultCount;penalty+=25;}else if(f.severity==DiagnosticSeverity::Warning){++s.warningCount;penalty+=10;}else{++s.advisoryCount;penalty+=3;}}s.healthScore=std::clamp(100.0-penalty,0.0,100.0);std::vector<std::string> t{s.scenario,std::string(p)};for(const auto& f:s.findings)t.push_back(f.code);std::sort(t.begin(),t.end());std::uint64_t h=1469598103934665603ULL;for(const auto& x:t){for(unsigned char c:x){h^=static_cast<std::uint64_t>(c);h*=1099511628211ULL;}h^=0xffULL;h*=1099511628211ULL;}std::ostringstream o;o<<std::hex<<std::setw(16)<<std::setfill('0')<<h;s.fingerprint=o.str();}}
void PlatformDiagnosticRules::augment(std::string_view platformId,std::uint64_t tick,const std::map<std::string,SensorSample>& sensors,DiagnosticSummary& summary){const auto p=AircraftPlatformCatalog::find(platformId);if(!p)return;for(const auto& r:p->diagnosticRules){const auto it=sensors.find(r.channel);if(it==sensors.end()||!it->second.valid||!hit(r,it->second.value))continue;if(std::any_of(summary.findings.begin(),summary.findings.end(),[&](const auto& f){return f.code==r.code;}))continue;DiagnosticFinding f;f.code=r.code;f.system=r.system;f.category=r.category;f.severity=sev(r.severity);f.title=r.title;f.probableCause="Synthetic platform-specific training condition or bounded injected fault.";f.isolation="Correlate the platform channel with its Digital Twin node, event timeline and adjacent valid samples.";f.recovery="Return the channel inside the configured platform training envelope and verify stable nominal state across consecutive frames.";f.confidence=.95;f.priority=f.severity==DiagnosticSeverity::Fault?98:68;f.evidence.push_back({"platform-telemetry",r.channel,num(it->second.value)+" "+it->second.unit,r.comparison+" threshold "+num(r.threshold),tick,1.0});summary.findings.push_back(std::move(f));summary.recommendations.push_back("Review "+p->name+" profile-specific evidence before closing the diagnostic case.");}finish(platformId,summary);}
} // namespace nexvary::avionics
